// === Tab: mySketch ===
const flowers = []
const flowers_num = 50
const bg_color = 'white'
const step = 12

setup = () => {
  createCanvas(windowWidth, windowHeight)
  background(bg_color)
  colorMode(HSB, 360)
  noFill()
  for (let i = flowers_num; i--;)
    flowers[i] = createVector(random(width * .1, width * .9), random(height * .1, height * .9))
}

draw = () => {
  const sec = frameCount / 30
  stroke(map(sin(sec), -1, 1, 0, 360), 360, 360)
  strokeWeight(1.5)
  for (let {x, y} of flowers) {
    beginShape()
    for (let i = 200; i--;) {
      let degree = sec
      for (const b of flowers) degree += atan2(b.y - y, b.x - x) * 2
      vertex(x += cos(degree) * step, y += sin(degree) * step)
      if (flowers.some(e => (e.x - x) ** 2 + (e.y - y) ** 2 < step )) break
    }
    endShape()
  }
}

mousePressed=()=>setup()
